import{_ as e,o as a,c as t,a4 as s}from"./chunks/framework.B-wJupoK.js";const o="/assets/image-20260805111217198.DTk4LFD2.png",i="/assets/image-20260805102827621.D6UsEcUP.png",g="/assets/image-20260805102921091.QEPVgYMs.png",r="/assets/image-20260805102954932.CE_P0x3i.png",p="/assets/image-20260805104432121.CpzOyjbf.png",l="/assets/image-20260805104553806.Blxbsjxv.png",d="/assets/image-20260805105526036.DsB3AEhg.png",c="/assets/image-20260805105224999.DfxAq31O.png",m="/assets/image-20260805105239418.BqBPH0Oh.png",v="/assets/image-20260805105856746.HW3h6G7S.png",h="/assets/image-20260805110139139.DC8U57nM.png",b="/assets/image-20260805110447267.CjDIf8bt.png",_="/assets/image-20260805121949073.BTPIJa-_.png",u="/assets/image-20260805121100934.DSQc9qQo.png",k="/assets/image-20260805121355530.CyEFlzJe.png",q="/assets/image-20260805121448855.H6FmUJSk.png",E="/assets/image-20260805121733870.Df04qNUn.png",S="/assets/image-20260805121846273.uetsABG6.png",D=JSON.parse('{"title":"万少暑假作业：用 Seed-Evolving 给小孩做一个家庭工作台","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/用 Seed-Evolving 给小孩做一个家庭工作台/用 Seed-Evolving 给小孩做一个家庭工作台.md","filePath":"AI人工智能/用 Seed-Evolving 给小孩做一个家庭工作台/用 Seed-Evolving 给小孩做一个家庭工作台.md","lastUpdated":1785904611000,"__rawMarkdown":"# 万少暑假作业：用 Seed-Evolving 给小孩做一个家庭工作台\\n\\n> 个人站点\\n>\\n> https://blog.zbztb.cn/\\n\\n\\n\\n## 前言\\n\\n​\\t大家好，我是万少，放暑假了，小孩最近都是在家里呆，吃喝拉撒的计划都比较随意，不像之前在学校那么的有规律，万少希望有一个工具可以很方便帮我对小孩的饮食、学习、作息、习惯等进行记录。\\n\\n> 访问地址：\\n>\\n> https://gongzuotai.zbztb.cn/#/\\n\\n\\n\\n![](assets/image-20260805111217198.png)\\n\\n## 模型选择\\n\\n​\\t因为这个**家庭儿童工作台**的要求还不少，直观的需求有：UI效果要好看、功能稳定、模块之间的数据可以联动等等，因为这个是MVP产品，所以数据库优先考虑存储在本地 IndexDB。\\n\\n\\n\\n​\\t结合上面的需求，万少这里选择使用的是火山引擎最新发布的**Seed-Evolving**模型，**Seed-Evolving** 是面向 **Agent** 与 Coding 场景打造的 Seed 系列模型，具备复杂任务编排、长程规划、代码生成与工具调用能力，它是多模态、支持1M超大上下文容量。这个很符合我当前的技术要求。\\n\\n\\n\\n​\\t使用**Seed-Evolving**对开发者比较友好的是，该模型是持续进化和升级到，但是不需要开发者主动记忆它的版本号，它永远沿用最新版本，减少开发者使用时候的心智负担。\\n\\n> 文末附接入**Seed-Evolving**模型指南；\\n\\n\\n\\n## 提需求\\n\\n​\\t优先在你喜欢的AI工具中 提出你的需求，**TraeWork**、**WorkBuddy**、**Qoder**等都可以。\\n\\n```\\n我想要开发一个最近 小红书上比较火的 家庭儿童工作台，它可以给家庭中的小孩提供常见服务（饮食、学习管理）等 要求是web网页形式，数据使用本地存储，要求单机可以使用，具有发送标准化邮件功能 -- 请你根据我大概的需求，和我对齐计划，然后帮我把详细的开发计划存到本地桌面md文件上\\n```\\n\\n![](assets/image-20260805102827621.png)\\n\\n​\\t稍等片刻，文档得到。\\n\\n![image-20260805102921091](assets/image-20260805102921091.png)\\n\\n​\\t内容一览\\n\\n![](assets/image-20260805102954932.png)\\n\\n​\\t开发文档还是很细致的，包含有、项目定位、技术选型、功能模块、数据模型等我们比较关心的部分，\\n\\n接下来可以根据需求来微调当前文档，其实万少后面没有调整，就直接使用了。\\n\\n## 执行计划\\n\\n\\n\\n​\\t接下来，让你的AI工具开始执行这个开发计划吧。\\n\\n![](assets/image-20260805104432121.png)\\n\\n可以看到，这个开发时间在15分钟之内就帮我搭建好了，如果类似以前的传统开发，起码要一个月的开发时间，效率提升巨大。\\n\\n而且也直接可以在本地运行起来。\\n\\n![](assets/image-20260805104553806.png)\\n\\n## 微调\\n\\n### 添加食谱\\n\\n​\\t其实万少一开始就是想要一个可以使用的家庭儿童工作台，很多的一些细节和需求其实没有想太多的，那么在把工作台跑起来之后，就可以继续微调。\\n\\n​\\t比如在饮食管理模块中，一开始食谱库里面是没有预置一些食谱的，那就希望这个工作台可以内置一些常用的食谱，同时也可以新增食谱，如下图。\\n\\n![](assets/image-20260805105526036.png)\\n\\n---\\n\\n\\n\\n![](assets/image-20260805105224999.png)\\n\\n---\\n\\n![](assets/image-20260805105239418.png)\\n\\n---\\n\\n### 添加主题\\n\\n然后，这个工作台默认只有一套粉色的主题，作为猛男的万少表示不能接受，于是我让它继续帮我添加一些主题。\\n\\n![](assets/image-20260805105856746.png)\\n\\n\\n\\n---\\n\\n​\\t一杯咖啡的功夫，皮肤就已经做好了了，**清爽明亮**、**护眼夜间**、**樱粉活力**，万少表示这种一点就透、一做就对的**Seed-Evolving**模型能力很满意。\\n\\n### 修复隐含bug\\n\\n​\\t然后我感觉功能差不多了，就让AI自己做个全面测试，帮我排查和修复一些我可能感知不到的Bug。\\n\\n![](assets/image-20260805110139139.png)\\n\\n​\\t结果呢，12分钟的时间，它还真给我排查出来了2个隐藏的Bug，可真是太贴心了，要是等到真实上线后再去发现，说不定还会导致我的真实数据出现异常呢，这个给点赞**Seed-Evolving**了。\\n\\n\\n\\n### 修改名字和新建favicon图标\\n\\n​\\t最后剩下的就是一些小微调，比如这个网站**缺少favicon**图标、这个**家庭儿童工作台**的名字不够有标志等等，万少就一并让它去帮我解决了。\\n\\n![](assets/image-20260805110447267.png)\\n\\n​\\t最后可以达到使用的标准了，小孩这个暑假的数据就到在我掌握之中了。\\n\\n![](assets/image-20260805121949073.png)\\n\\n## Seed-Evolving 接入指南\\n\\n接下来万少介绍一下如何开通和使用 Seed-Evolving 。\\n\\n> https://ark.volcengine.com/region:cn-beijing/docs/82379/1399008?lang=zh\\n\\n\\n\\n### 按量付费接入或者购买包月套餐\\n\\nSeed-Evolving支持API接入（按量付费）和包月套餐的方式使用，万少这里建议是购买包月套餐，按量付费可能会出现费用超出预期的情况。\\n\\n```\\nhttps://ark.volcengine.com/region:cn-beijing/subscription/agent-plan\\n```\\n\\n![](assets/image-20260805121100934.png)\\n\\n根据需求选择套餐，万少这里选择的是**49.9元/月**\\n\\n\\n\\n### 获取接入的API KEY\\n\\n> https://ark.volcengine.com/region:cn-beijing/model/detail?_vtm_=a441938.b75322.0_0.0_0.0.58_7650357318802048575&name=doubao-seed-evolving\\n\\n![](assets/image-20260805121355530.png)\\n\\n![](assets/image-20260805121448855.png)\\n\\n### 配置到你的模型中\\n\\n万少这里以**Trae Work**为例\\n\\n**设置** ->  **模型**  -> **添加模型**  ->  **填入信息**\\n\\n![](assets/image-20260805121733870.png)\\n\\n最后在对话窗口中指定模型开始使用\\n\\n![](assets/image-20260805121846273.png)\\n\\n## 总结\\n\\n这一趟下来，万少最大的感受是：Seed-Evolving 让**一个想法**到**一个能用的工作台**之间的距离，被压缩到了一杯咖啡的时间。\\n\\n回顾整个过程，**Seed-Evolving** 的几项核心能力贯穿始终：\\n\\n- **长程规划与任务编排**：从一句模糊的需求，自动拆解成项目定位、技术选型、功能模块、数据模型等完整开发计划，不需要我一项项列清单。\\n- **代码生成与工具调用**：15 分钟内完成从开发到本地可运行的闭环，这正是 Agent 与 Coding 场景下模型的拿手好戏。\\n- **多模态 + 1M 超大上下文**：不管是内置食谱、新增主题皮肤，还是 favicon 图标，模型都能一次性理解多个模块的上下文并给出改动，改完各处仍然一致。\\n- **持续进化、无需记版本号**：模型自动沿用最新版本，我作为开发者不用分心去追更，心智负担轻了很多。\\n\\n\\n\\n而最让我意外的，是让它**\\"自己给自己做全面测试\\"**这一步——12 分钟排查出 2 个我根本感知不到的隐藏 Bug。这意味着 Seed-Evolving 不只是 **听话照做** 的代码生成器，而是具备一定**自我审视与质量保障能力**的 Agent 模型。\\n\\n如果你也有一个\\"想做但一直没动手\\"的小工具想法，不妨用 Seed-Evolving 试试，**先把 MVP 跑起来，剩下的就是边用边微调的事了。**\\n\\n> 💡 **行动建议**：先按文末指南开通 Seed-Evolving，再用一句需求把开发计划对齐出来，然后让它 15 分钟帮你把成品搭出来。哪怕最后不用，这个过程本身也是一次很好的 AI Coding 实操。"}'),f={name:"AI人工智能/用 Seed-Evolving 给小孩做一个家庭工作台/用 Seed-Evolving 给小孩做一个家庭工作台.md"};function P(A,n,x,I,z,B){return a(),t("div",null,[...n[0]||(n[0]=[s("",76)])])}const T=e(f,[["render",P]]);export{D as __pageData,T as default};
